*Institutional Holdings (inst_own contains total institutional holdings from WRDS Thomson financial (tfn.s34) by cusip, ticker, rdate); 
DATA inst0; set EP.inst_own; if year(rdate)>=2004; RUN;

PROC SQL;
	create table inst1 as
	select A.*, B.permno, B.permco
	from inst0 as A, EP.crsp_stocknames as B
	where A.cusip=B.ncusip and B.namedt<=A.rdate<=B.nameenddt and B.shrcd in (10 11);

DATA bex0; set EP.na_wrds_org_summary; if rowtype="Board Member" and cikcode^=''; 
	keep cikcode annualreportdate rolename numberdirectors directorid totcurrnolstdbrd totcurrnounlstdbrd totcurrnoothlstdbrd; 
PROC SORT noduprecs; by _all_; RUN;

DATA rm0; set EP.rmdirectors; 
	cusip8=substrn(cusip, 1, 8);
	if substrn(classification, 1, 1)="I" then indep=1; else if classification^='' then indep=0;
RUN;

