DATA sp0; set EP.vavoteresults (keep = companyid cusip meetingid itemonagendaid issagendaitemid meetingdate voteresult meetingtype recorddate votedfor votedagainst votedabstain);
	if issagendaitemid in ('M0524' 'M0522' 'M0503' 'M0501' 'M0526' 'M0599' 'M0507' 'M0598' 'M0509' 'M0525' 'M0597' 'M0530' 'M0528');
	if voteresult in ('Pass' 'Fail') and meetingtype='Annual' and votedfor^=0;
	fpct=votedfor/(votedfor+votedagainst+votedabstain);

